CREATE OR REPLACE FUNCTION public.fn_ca_incident_resolution_reaches_the_alerts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_note text; v_state text; v_msg text;
BEGIN
  IF NEW.status <> 'resolved' OR
     (COALESCE(OLD.status,'') = 'resolved'
      AND NEW.closure_basis IS NOT DISTINCT FROM OLD.closure_basis) THEN
    RETURN NEW;
  END IF;

  /* AN AGE-OUT IS NOT A RESOLUTION AND MUST NOT PROPAGATE AS ONE (2026-09-20).
     This trigger marks the financial_alerts rows behind an incident resolved.
     An incident retired only because its stream went quiet has established
     nothing about those alerts, so closing them would carry "I could not tell"
     into a second table dressed as an answer. The incident closes; the alert
     stays open for whoever reads financial_alerts directly. */
  IF COALESCE(NEW.closure_basis = 'aged_out_unverified', false) THEN
    RETURN NEW;
  END IF;

  v_note := 'Closed with drift incident ' || NEW.id::text || ': '
            || COALESCE(NULLIF(NEW.resolution,''), 'no note given on the incident');

  UPDATE public.financial_alerts f
     SET resolved = true, resolved_at = now(),
         resolution = COALESCE(NULLIF(f.resolution,'') || ' | ','') || v_note
   WHERE NOT COALESCE(f.resolved,false)
     AND f.context->>'incident_id' ~ '^[0-9a-fA-F-]{36}$'
     AND (f.context->>'incident_id')::uuid = NEW.id;

  IF NEW.metadata->>'alert_id' ~ '^[0-9a-fA-F-]{36}$' THEN
    UPDATE public.financial_alerts f
       SET resolved = true, resolved_at = now(),
           resolution = COALESCE(NULLIF(f.resolution,'') || ' | ','') || v_note
     WHERE NOT COALESCE(f.resolved,false)
       AND f.id = (NEW.metadata->>'alert_id')::uuid;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Explicit operator resolution must commit its linked outcome atomically.
  IF NEW.closure_basis = 'operator' THEN RAISE; END IF;
  GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
  BEGIN
    INSERT INTO public.ca_incident_file_failures
      (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
    VALUES ('fn_ca_incident_resolution_reaches_the_alerts',
            'propagate:incident->alert:' || NEW.id::text,
            'unknown', 'warning', 0, v_state,
            'a resolved incident did not close the alerts echoing it: ' || v_msg);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RAISE WARNING 'fn_ca_incident_resolution_reaches_the_alerts failed: %', v_msg;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_operational_alert_mirror_classify()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_prefix text; v_aid text; v_rule text; v_prev_res boolean; v_prev_sr integer;
BEGIN
  IF NEW.investigation_status IS DISTINCT FROM 'new' THEN RETURN NEW; END IF;
  IF NEW.source IN ('financial-alerts-backfill', 'financial-alerts-updates', 'drift-incidents-backfill', 'drift-incidents-updates') THEN
    v_prefix := CASE WHEN NEW.source LIKE 'financial-alerts-%' THEN 'financial-alerts' ELSE 'drift-incidents' END;
    v_aid := split_part(NEW.event_key, ':', 1);
    IF NEW.source = v_prefix || '-updates' AND NEW.status = 'resolved' THEN
      v_rule := 'mirror_resolution_receipt';
    ELSIF NEW.source = v_prefix || '-updates' AND NEW.status = 'firing' THEN
      SELECT bool_or(o.status = 'resolved'), max(public.fn_operational_alert_severity_rank(o.severity))
        INTO v_prev_res, v_prev_sr
        FROM public.operational_alert_events o
       WHERE split_part(o.event_key, ':', 1) = v_aid AND o.source IN (v_prefix || '-backfill', v_prefix || '-updates');
      IF v_prev_sr IS NOT NULL AND NOT coalesce(v_prev_res, false)
         AND public.fn_operational_alert_severity_rank(NEW.severity) <= v_prev_sr THEN
        v_rule := 'mirror_duplicate_of_captured_original';
      END IF;
    ELSIF NEW.source = v_prefix || '-backfill' AND NEW.status = 'resolved' AND NEW.severity = 'info' THEN
      v_rule := 'info_captured_already_resolved';
    END IF;
  ELSIF NEW.source = 'alertmanager' AND NEW.status = 'resolved' THEN
    IF EXISTS (SELECT 1 FROM public.operational_alert_events f
                WHERE f.source = 'alertmanager' AND f.status = 'firing' AND f.alertname = NEW.alertname
                  AND (f.payload -> 'alert') ->> 'fingerprint' = (NEW.payload -> 'alert') ->> 'fingerprint'
                  AND (f.payload -> 'alert') ->> 'startsAt' = (NEW.payload -> 'alert') ->> 'startsAt') THEN
      v_rule := 'alertmanager_resolution_receipt_of_captured_firing';
    END IF;
  END IF;
  IF v_rule IS NOT NULL THEN
    NEW.investigation_status := 'informational';
    NEW.investigation := coalesce(NEW.investigation, '{}'::jsonb) || jsonb_build_object(
      'closed_by', 'alert-quality-rule-2026-10-31', 'rule', v_rule,
      'evidence', 'Classified on arrival: this receipt repeats or resolves an alert the inbox already holds.');
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END
$function$
